"use client";

import React, { useState, useMemo, useEffect } from "react";
import { 
  CalendarDays, MapPin, Flag, ChevronDown, 
  Search, Filter, Plus, Minus, Sparkles, Globe 
} from "lucide-react";

/* --- 1. DATASET --- */
const HOLIDAYS_DB = [
  // --- JANUARY 2026 ---
  { id: 101, name: "New Year's Day", date: "Jan 01", monthIdx: 0, day: "Thu", year: "2026", type: "Public", country: "Global", region: "All" },
  { id: 102, name: "Lohri", date: "Jan 13", monthIdx: 0, day: "Tue", year: "2026", type: "Optional", country: "India", region: "North India" },
  { id: 103, name: "Pongal", date: "Jan 14", monthIdx: 0, day: "Wed", year: "2026", type: "Optional", country: "India", region: "Karnataka" },
  { id: 104, name: "Republic Day", date: "Jan 26", monthIdx: 0, day: "Mon", year: "2026", type: "National", country: "India", region: "All" },
  
  // --- FEBRUARY 2026 ---
  { id: 201, name: "Presidents' Day", date: "Feb 16", monthIdx: 1, day: "Mon", year: "2026", type: "Public", country: "USA", region: "All" },
  
  // --- MARCH 2026 ---
  { id: 301, name: "Maha Shivaratri", date: "Mar 08", monthIdx: 2, day: "Sun", year: "2026", type: "Optional", country: "India", region: "All" },
  { id: 302, name: "Holi", date: "Mar 14", monthIdx: 2, day: "Sat", year: "2026", type: "Optional", country: "India", region: "All" },
  { id: 303, name: "Ugadi", date: "Mar 19", monthIdx: 2, day: "Thu", year: "2026", type: "Optional", country: "India", region: "Telangana" },
  
  // --- APRIL 2026 ---
  { id: 401, name: "Good Friday", date: "Apr 03", monthIdx: 3, day: "Fri", year: "2026", type: "Public", country: "Global", region: "All" },
  
  // --- MAY 2026 ---
  { id: 501, name: "Labor Day", date: "May 01", monthIdx: 4, day: "Fri", year: "2026", type: "Public", country: "Global", region: "All" },
  { id: 502, name: "Memorial Day", date: "May 25", monthIdx: 4, day: "Mon", year: "2026", type: "Public", country: "USA", region: "All" },

  // --- AUGUST 2026 ---
  { id: 801, name: "Independence Day", date: "Aug 15", monthIdx: 7, day: "Sat", year: "2026", type: "National", country: "India", region: "All" },
];

const MONTH_NAMES = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
const YEAR_OPTIONS = ["2024", "2025", "2026", "2027", "2028", "2029"];

const REGIONS_BY_COUNTRY: any = {
    "All": ["All", "Telangana", "Karnataka", "North India", "New York"],
    "India": ["All", "Telangana", "Karnataka", "North India"],
    "USA": ["All", "New York", "California"],
    "Global": ["All"]
};

export default function AccordionHolidayHub() {
  const [year, setYear] = useState("2026");
  const [country, setCountry] = useState("All");
  const [region, setRegion] = useState("All");
  const [type, setType] = useState("All");

  /* --- LOGIC ENGINE --- */
  const groupedHolidays = useMemo(() => {
    const filtered = HOLIDAYS_DB.filter((h) => {
      const matchYear = h.year === year;
      const matchCountry = country === "All" || h.country === country || h.country === "Global";
      const matchRegion = region === "All" || h.region === region || h.region === "All";
      const matchType = type === "All" || h.type === type;
      return matchYear && matchCountry && matchRegion && matchType;
    });

    filtered.sort((a, b) => a.monthIdx - b.monthIdx);

    const groups: Record<string, typeof filtered> = {};
    // Ensure all months are keys (optional, but good for empty states) or just dynamic
    filtered.forEach(h => {
        const monthKey = MONTH_NAMES[h.monthIdx];
        if (!groups[monthKey]) groups[monthKey] = [];
        groups[monthKey].push(h);
    });

    return groups;
  }, [year, country, region, type]);

  return (
    <div className="flex-1 h-screen overflow-y-auto bg-[#F8F9FC] dark:bg-[#050505]">
      
      {/* --- STICKY HEADER --- */}
      <header className="sticky top-0 z-30 bg-white/80 dark:bg-[#121212]/80 backdrop-blur-md border-b border-slate-200 dark:border-slate-800 px-6 py-4">
         <div className="max-w-5xl mx-auto flex flex-col xl:flex-row items-center justify-between gap-4">
            
            <div className="flex items-center gap-3 w-full xl:w-auto">
               <div className="p-2 bg-brand-50 dark:bg-brand-500/10 text-brand-600 rounded-lg">
                  <CalendarDays size={20} />
               </div>
               <div>
                  <h1 className="text-lg font-bold text-slate-900 dark:text-white leading-none">Holiday Calendar</h1>
                  <p className="text-xs font-medium text-slate-500 mt-1">Official Schedule • {year}</p>
               </div>
            </div>

            <div className="flex flex-wrap items-center gap-2 w-full xl:w-auto">
                {/* Type Filter */}
                <div className="bg-slate-100 dark:bg-slate-800 p-1 rounded-lg flex items-center">
                    {['All', 'Public', 'Optional'].map((t) => (
                        <button
                            key={t}
                            onClick={() => setType(t)}
                            className={`px-3 py-1.5 rounded-md text-[10px] font-bold uppercase tracking-widest transition-all ${
                                type === t 
                                ? "bg-white dark:bg-slate-600 text-slate-900 dark:text-white shadow-sm" 
                                : "text-slate-500 hover:text-slate-700 dark:hover:text-slate-300"
                            }`}
                        >
                            {t}
                        </button>
                    ))}
                </div>

                <div className="h-6 w-[1px] bg-slate-200 dark:bg-slate-700 mx-1 hidden md:block" />

                <CompactSelect icon={<Flag size={14} />} value={country} onChange={(v: string)=>{setCountry(v); setRegion('All')}} options={['All', 'India', 'USA']} />
                <CompactSelect icon={<MapPin size={14} />} value={region} onChange={setRegion} options={REGIONS_BY_COUNTRY[country] || ['All']} disabled={country === 'Global'} />
                <CompactSelect icon={<Filter size={14} />} value={year} onChange={setYear} options={YEAR_OPTIONS} highlight={true} />
            </div>
         </div>
      </header>

      {/* --- ACCORDION CONTENT --- */}
      <main className="max-w-5xl mx-auto px-6 py-8 pb-24 space-y-4">
         {Object.keys(groupedHolidays).length > 0 ? (
            Object.keys(groupedHolidays).map((month) => (
               <MonthAccordion 
                  key={month} 
                  monthName={month} 
                  holidays={groupedHolidays[month]} 
                  isDefaultOpen={month === "January"} // Open Jan by default
               />
            ))
         ) : (
            <div className="py-20 text-center border-2 border-dashed border-slate-200 dark:border-slate-800 rounded-2xl">
               <Search className="w-10 h-10 text-slate-300 mx-auto mb-3" />
               <p className="text-sm font-bold text-slate-500">No holidays found for these filters.</p>
               <button onClick={()=>{setCountry('All'); setType('All')}} className="mt-2 text-xs text-brand-600 font-bold hover:underline">Reset</button>
            </div>
         )}
      </main>
    </div>
  );
}

/* --- ACCORDION COMPONENT --- */
const MonthAccordion = ({ monthName, holidays, isDefaultOpen }: any) => {
    const [isOpen, setIsOpen] = useState(isDefaultOpen);

    // Count types for the preview dots
    const publicCount = holidays.filter((h: any) => h.type !== 'Optional').length;
    const optionalCount = holidays.filter((h: any) => h.type === 'Optional').length;

    return (
        <div className="bg-white dark:bg-[#121212] border border-slate-200 dark:border-slate-800 rounded-2xl overflow-hidden transition-all duration-300 hover:border-brand-500/30">
            
            {/* Header (Clickable) */}
            <button 
                onClick={() => setIsOpen(!isOpen)}
                className="w-full flex items-center justify-between p-5 hover:bg-slate-50 dark:hover:bg-white/5 transition-colors"
            >
                <div className="flex items-center gap-6">
                    {/* Month Identity */}
                    <div className="w-12 h-12 rounded-xl bg-slate-50 dark:bg-slate-800 flex items-center justify-center text-slate-500 dark:text-slate-400">
                        {isOpen ? <Minus size={20} /> : <Plus size={20} />}
                    </div>
                    
                    <div className="text-left">
                        <h3 className="text-lg font-black text-slate-900 dark:text-white uppercase tracking-tight">{monthName}</h3>
                        <div className="flex items-center gap-3 mt-1">
                            <span className="text-xs font-medium text-slate-400">{holidays.length} Events</span>
                            
                            {/* Visual Preview Dots */}
                            {!isOpen && (
                                <div className="flex gap-1">
                                    {Array.from({ length: Math.min(publicCount, 5) }).map((_, i) => (
                                        <div key={`p-${i}`} className="w-1.5 h-1.5 rounded-full bg-emerald-500" />
                                    ))}
                                    {Array.from({ length: Math.min(optionalCount, 5) }).map((_, i) => (
                                        <div key={`o-${i}`} className="w-1.5 h-1.5 rounded-full bg-amber-500" />
                                    ))}
                                </div>
                            )}
                        </div>
                    </div>
                </div>

                <div className={`transform transition-transform duration-300 ${isOpen ? 'rotate-180' : ''}`}>
                    <ChevronDown className="text-slate-300" />
                </div>
            </button>

            {/* Expanded Body */}
            {isOpen && (
                <div className="p-5 pt-0 border-t border-slate-100 dark:border-slate-800/50 animate-slide-down">
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3 mt-5">
                        {holidays.map((h: any) => (
                            <HolidayCard key={h.id} data={h} />
                        ))}
                    </div>
                </div>
            )}
        </div>
    );
};

/* --- CARD COMPONENT --- */
const HolidayCard = ({ data }: { data: any }) => (
    <div className="bg-slate-50 dark:bg-slate-900/50 border border-slate-100 dark:border-slate-800 rounded-xl p-3 flex gap-3 items-center hover:bg-white dark:hover:bg-slate-800 hover:shadow-md transition-all group cursor-default">
        {/* Date */}
        <div className="flex-shrink-0 w-12 h-12 bg-white dark:bg-slate-800 rounded-lg flex flex-col items-center justify-center border border-slate-200 dark:border-slate-700 text-slate-400 group-hover:text-brand-600 group-hover:border-brand-200 transition-colors">
            <span className="text-[9px] font-black uppercase">{data.day}</span>
            <span className="text-lg font-black leading-none">{data.date.split(' ')[1]}</span>
        </div>
        
        {/* Info */}
        <div className="flex-1 min-w-0">
            <div className="flex items-center gap-1.5 mb-0.5">
                {data.type === 'Optional' 
                    ? <Sparkles size={10} className="text-amber-500" /> 
                    : <Globe size={10} className="text-emerald-500" />
                }
                <span className={`text-[9px] font-black uppercase tracking-wide truncate ${
                    data.type === 'Optional' ? 'text-amber-600 dark:text-amber-500' : 'text-emerald-600 dark:text-emerald-500'
                }`}>
                    {data.type}
                </span>
            </div>
            <h4 className="text-sm font-bold text-slate-700 dark:text-slate-200 truncate group-hover:text-slate-900 dark:group-hover:text-white transition-colors">
                {data.name}
            </h4>
            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">{data.country === 'Global' ? 'Global' : data.region}</p>
        </div>
    </div>
);

/* --- UTILS --- */
const CompactSelect = ({ icon, value, onChange, options, disabled, highlight }: any) => (
   <div className={`relative h-9 min-w-[120px] ${disabled ? 'opacity-50 pointer-events-none' : ''}`}>
      <div className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none">{icon}</div>
      <select 
         value={value} 
         onChange={(e) => onChange(e.target.value)} 
         disabled={disabled}
         className={`w-full h-full pl-9 pr-8 text-xs font-bold uppercase tracking-widest outline-none cursor-pointer appearance-none rounded-lg border transition-all ${
            highlight 
            ? "bg-brand-50 text-brand-700 border-brand-100 dark:bg-brand-900/20 dark:text-brand-400 dark:border-brand-800" 
            : "bg-white dark:bg-slate-800 text-slate-700 dark:text-slate-200 border-slate-200 dark:border-slate-700 hover:border-slate-300"
         }`}
      >
         {options.map((opt: string) => <option key={opt} value={opt}>{opt}</option>)}
      </select>
      <ChevronDown size={14} className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
   </div>
);